const size_t num_threads = std::min(static_cast<size_t>(std::thread::hardware_concurrency()), end - start);
const size_t chunk_size = (end - start + num_threads - 1) / num_threads;

std::vector<std::thread> threads;
threads.reserve(num_threads);

auto calculate_chunk = [&](size_t chunk_start, size_t chunk_end) {
    for (size_t i = chunk_start; i < chunk_end; ++i) {
        const size_t idx = start + i;
        Particle& p = particles[idx];
        p.hash = static_cast<uint32_t>(std::floor(p.position.x / h)) |
                 (static_cast<uint32_t>(std::floor(p.position.y / h)) << 16) |
                 (static_cast<uint32_t>(std::floor(p.position.z / h)) << 32);
    }
};

for (size_t t = 0; t < num_threads; ++t) {
    size_t chunk_start = t * chunk_size;
    size_t chunk_end = std::min(chunk_start + chunk_size, end - start);
    threads.emplace_back(calculate_chunk, chunk_start, chunk_end);
}

for (auto& thread : threads) {
    if (thread.joinable()) {
        thread.join();
    }
}
// END_CODE

